import{_ as e,c as t,o as p,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"震下坤上 复：","description":"京氏易传 - 震下坤上 复：","frontmatter":{"title":"震下坤上 复：","description":"京氏易传 - 震下坤上 复："},"headers":[],"relativePath":"zh/classics/jingshi/035.md","filePath":"zh/classics/jingshi/035.md"}'),i={name:"zh/classics/jingshi/035.md"};function r(n,a,c,_,o,l){return p(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="震下坤上-复" tabindex="-1">震下坤上 复： <a class="header-anchor" href="#震下坤上-复" aria-label="Permalink to “震下坤上 复：”">​</a></h1><p>阴极则反，阳道行【一作正】也。《易》云：“君子道长，小人道消”。又曰：“七日来复”。【七日，阳之称也。七</p><p>九称阳之数也。谓坤上六，阴极阳战之地，阴虽不能胜阳，然正当盛，阳不可轻犯。六阳涉六阴反下，七爻在初，故称七日。</p><p>日亦阳也。】六爻反复之称。【注在前。】《易》云：“初九，不远复，无祗悔”。【反至初九，阳来阴复，去远也。】（虎易注：此字因为模糊，无法辨认，我是根据“不远复”之意，暂时一用，待以后有机会再确定。）六爻盛，卦之体总称也。</p><p>曰一阳为一卦之主，与震为飞伏。【庚子水，乙未土。】初九元士之世，六四诸侯见应。</p><p>建始乙未至庚子，【大暑大雪见候，起坤，六月至十一月，戊子为正朔，见复之兆。】积算起庚子至己亥，【积算起庚</p><p>子至己亥，十月至十一月，年亦然。】周而复始。土水见候。</p><p>五星从位起岁星，【岁星木星入复卦，合水土，配吉凶。】张宿从位降庚子，【二十八宿分张宿，入复卦庚子水上。】</p><p>分气候二十八。【积算起数二十八，定吉凶六爻。】</p><p>坤上震下，动而顺，是阳来荡阴，阴柔反去，刚阳复位，君子进，小人退。《易》云：“休复，元吉”。</p><p>阳升阴降，变六二入兑象，次併临，二阳将进，内为悦。阴来阳去，气渐隆，【阴不敢拒阳，奉命而已。】次降入地泽临卦。</p>',11)])])}const m=e(i,[["render",r]]);export{h as __pageData,m as default};
